 80	<main>
 81	  <h1>Todos</h1>
 82	  <form id="todo-form">
 83	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
 84	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
 85	    <select data-testid="todo-priority" aria-label="Priority">
 86	      <option value="low">Low</option>
 87	      <option value="med" selected>Med</option>
 88	      <option value="high">High</option>
 89	    </select>
 90	    <button type="submit" class="add" data-testid="todo-add">Add</button>
 91	  </form>
 92	  <div class="filters" role="group" aria-label="Filter todos">
 93	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
 94	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
 95	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
 96	  </div>
 97	  <ul data-testid="todo-list"></ul>
 98	  <p class="empty" hidden>No todos yet.</p>
 99	</main>
100	<script>
101	(function () {
102	  var STORAGE_KEY = 'todos';
103	  var form = document.getElementById('todo-form');
104	  var input = document.querySelector('[data-testid="todo-input"]');
105	  var dueInput = document.querySelector('[data-testid="todo-due"]');
106	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
107	  var list = document.querySelector('[data-testid="todo-list"]');
108	  var empty = document.querySelector('.empty');
109	  var filterButtons = document.querySelectorAll('[data-filter]');
110	
111	  var PRIORITIES = ['low', 'med', 'high'];
112	  var DEFAULT_PRIORITY = 'med';
113	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
114	
115	  function normalizePriority(p) {
116	    return PRIORITIES.indexOf(p) !== -1 ? p : DEFAULT_PRIORITY;
117	  }
118	
119	  function load() {
120	    try {
121	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
122	      if (!Array.isArray(data)) return [];
123	      // Todos saved before priorities existed default to "med".
124	      data.forEach(function (t) { t.priority = normalizePriority(t.priority); });
125	      return data;
126	    } catch (e) {
127	      return [];
128	    }
129	  }
130	
131	  function save() {
132	    try {
133	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
134	    } catch (e) {
135	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
136	    }
137	  }
138	
139	  function makeId() {
140	    if (window.crypto && typeof crypto.randomUUID === 'function') {
141	      return crypto.randomUUID();
142	    }
143	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
144	  }
145	
146	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
147	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
148	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
149	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
150	
151	  function pad(n) { return (n < 10 ? '0' : '') + n; }
152	
153	  function todayLocal() {
154	    var d = new Date();
155	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
156	  }
157	
158	  // Overdue: due date strictly before today's local date. Due today is never overdue.
159	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
160	  function isOverdue(todo, today) {
161	    return !!todo.due && todo.due < today;
162	  }
163	
164	  function formatDue(due) {
165	    var parts = due.split('-');
166	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
167	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
168	  }
169	
170	  var todos = load();
171	  var filter = 'all';
172	  var renderedDay = null;
173	
174	  // Ordering rule (project decision): active todos first, completed todos below.
175	  // Within each group, keep insertion order (oldest first). `todos` is stored
176	  // in insertion order, so splitting it into two groups preserves that.
177	  function visibleTodos() {
178	    var active = todos.filter(function (t) { return !t.completed; });
179	    var completed = todos.filter(function (t) { return t.completed; });
180	    if (filter === 'active') return active;
181	    if (filter === 'completed') return completed;
182	    return active.concat(completed);
183	  }
184	
185	  function render() {
186	    list.textContent = '';
187	    var visible = visibleTodos();
188	    var today = todayLocal();
189	    renderedDay = today;
190	    visible.forEach(function (todo) {
191	      var li = document.createElement('li');
192	      li.setAttribute('data-testid', 'todo-item');
193	      li.setAttribute('data-id', todo.id);
194	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
195	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
196	      li.setAttribute('data-priority', todo.priority);
197	
198	      var toggle = document.createElement('input');
199	      toggle.type = 'checkbox';
200	      toggle.checked = !!todo.completed;
201	      toggle.setAttribute('data-testid', 'todo-toggle');
202	      toggle.setAttribute('aria-label', 'Mark complete');
203	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
204	
205	      var text = document.createElement('span');
206	      text.className = 'text';
207	      text.setAttribute('data-testid', 'todo-text');
208	      text.textContent = todo.text;
209	
210	      var del = document.createElement('button');
211	      del.type = 'button';
212	      del.className = 'delete';
213	      del.setAttribute('data-testid', 'todo-delete');
214	      del.setAttribute('aria-label', 'Delete todo');
215	      del.textContent = 'Delete';
216	      del.addEventListener('click', function () { remove(todo.id); });
217	
218	      var priority = document.createElement('span');
219	      priority.className = 'priority';
220	      priority.setAttribute('data-testid', 'todo-priority-label');
221	      priority.textContent = PRIORITY_LABELS[todo.priority];
222	
223	      li.appendChild(toggle);
224	      li.appendChild(text);
225	      li.appendChild(priority);
226	      if (todo.due) {
227	        var due = document.createElement('time');
228	        due.className = 'due';
229	        due.setAttribute('data-testid', 'todo-due-date');
230	        due.setAttribute('datetime', todo.due);
231	        due.textContent = 'Due ' + formatDue(todo.due);
232	        li.appendChild(due);
233	      }
234	      li.appendChild(del);
235	      list.appendChild(li);
236	    });
237	    empty.textContent = todos.length === 0 ? 'No todos yet.'
238	      : filter === 'active' ? 'No active todos.'
239	      : 'No completed todos.';
240	    empty.hidden = visible.length > 0;
241	    filterButtons.forEach(function (btn) {
242	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
243	    });
244	  }
245	
246	  function add(text, due, priority) {
247	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
248	    save();
249	    render();
250	  }
251	
252	  function remove(id) {
253	    todos = todos.filter(function (t) { return t.id !== id; });
254	    save();
255	    render();
256	  }
257	
258	  function setCompleted(id, completed) {
259	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
260	    save();
261	    render();
262	  }
263	
264	  filterButtons.forEach(function (btn) {
265	    btn.addEventListener('click', function () {
266	      filter = btn.getAttribute('data-filter');
267	      render();
268	    });
269	  });
270	
271	  form.addEventListener('submit', function (e) {
272	    e.preventDefault();
273	    var text = input.value.trim();
274	    if (!text) return;
275	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
276	    add(text, due, priorityInput.value);
277	    input.value = '';
278	    dueInput.value = '';
279	    priorityInput.value = DEFAULT_PRIORITY;
280	    input.focus();
281	  });
282	
283	  render();
284	
285	  // Overdue status changes at local midnight; re-render when the day rolls over.
286	  setInterval(function () {
287	    if (todayLocal() !== renderedDay) render();
288	  }, 30000);
289	})();
290	</script>
291	</body>
292	</html>

